def fitoe(ins,n,files,trials=4,seed=1,maxnfev=200,p0=None):
    def unpack(p):
        den=np.r_[1,p[:n]]; nums=[p[n+i*(n+1):n+(i+1)*(n+1)] for i in range(len(ins))]; return den,nums
    def res(p):
        den,nums=unpack(p)
        if np.any(np.real(np.roots(den))>0): return np.ones(sum(len(YQ[f]) for f in files))
        return np.concatenate([sim_tf(den,nums,ins,f)-YQ[f] for f in files])
    best=None; rng=np.random.default_rng(seed)
    for trial in range(trials):
        if p0 is None or trial>0:
            poles=-np.exp(rng.uniform(np.log(0.1),np.log(30),n)); den=np.real(np.poly(poles))
            pp=np.r_[den[1:],rng.normal(0,5,len(ins)*(n+1))]
        else: pp=p0
        s=least_squares(res,pp,max_nfev=maxnfev); c=np.sqrt(np.mean(s.fun**2))
        if best is None or c<best[0]: best=(c,s.x)
    c,p=best; den,nums=unpack(p)
    print(ins,n,'%.5f'%c,'poles',np.roots(den).round(3))
    for k,nm in zip(ins,nums): print('   ',k,nm.round(3),'dc %.3f'%(nm[-1]/den[-1]))
    print('   ',' '.join('%s %.4f'%(f[-14:],np.sqrt(np.mean((sim_tf(den,nums,ins,f)-YQ[f])**2))) for f in TR+VA))
